import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Agent Autonomy: From Assistance to Independent Action","description":"","frontmatter":{},"headers":[],"relativePath":"learn/01-agent-basics/autonomy-levels.md","filePath":"learn/01-agent-basics/autonomy-levels.md","lastUpdated":1792595354000}'),s={name:"learn/01-agent-basics/autonomy-levels.md"};function i(r,e,d,c,l,m){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-autonomy-from-assistance-to-independent-action" tabindex="-1">Agent Autonomy: From Assistance to Independent Action <a class="header-anchor" href="#agent-autonomy-from-assistance-to-independent-action" aria-label="Permalink to &quot;Agent Autonomy: From Assistance to Independent Action&quot;">​</a></h1><p>Autonomy describes how much of a task an agent can complete without a person selecting every next step. It is not a single measure of intelligence or safety: an agent may gather information independently but need approval before spending money.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Agent role</th><th>Human role</th></tr></thead><tbody><tr><td><strong>Assist</strong></td><td>Drafts or recommends</td><td>Reviews and performs the action</td></tr><tr><td><strong>Confirm each action</strong></td><td>Proposes an operation</td><td>Approves each consequential step</td></tr><tr><td><strong>Bounded autonomy</strong></td><td>Acts within explicit limits</td><td>Sets policy and handles exceptions</td></tr><tr><td><strong>Delegated execution</strong></td><td>Completes a multi-step task</td><td>Defines goal, constraints, and escalation points</td></tr></tbody></table><p>These are practical categories, not a universal formal standard. Match autonomy to potential harm, maximum loss, reversibility, effects on third parties, and the user&#39;s ability to inspect and stop the action. Too many prompts create approval fatigue; too few remove meaningful control.</p><h2 id="define-enforceable-boundaries" tabindex="-1">Define enforceable boundaries <a class="header-anchor" href="#define-enforceable-boundaries" aria-label="Permalink to &quot;Define enforceable boundaries&quot;">​</a></h2><p>Specify allowed tools and recipients, amount caps, budgets, rate limits, deadlines, and conditions that require review. Enforce these constraints outside the model. For uncertain outcomes, define a recovery path: a payment timeout should trigger reconciliation, not an automatic second payment.</p><p>Start with observation or recommendations, then enable narrow actions in a test environment. Review traces and failure cases before expanding permissions. Provide ways to pause tasks, revoke credentials, and inspect action history.</p><p>Autonomy should be granted per capability and bounded by the consequences of failure. The goal is useful execution within clear limits, not maximum independence.</p>',8)])])}const h=t(s,[["render",i]]);export{u as __pageData,h as default};
